const cmds = [
  ["tree","find . -maxdepth 5 -type f -not -path './.git/*' -not -name '*.safetensors' -not -name '*.bin' -not -name '*.onnx' -not -name '*.index' -not -name '*.lock' -print | sort","/workspace"],
  ["sizes","du -ah experiment_logs outputs historical_evidence nq_hotpotqa_train 2>/dev/null | sort -h","/workspace"],
  ["git","git status --short && git log -1 --oneline --decorate 2>/dev/null || true","/workspace"]
];
const rs = await Promise.allSettled(cmds.map(async ([label,cmd,workdir]) => ({label, ...(await tools.exec_command({cmd,workdir,yield_time_ms:10000,max_output_tokens:30000}))})));
for (const r of rs) { if (r.status==="fulfilled") { text(`--- ${r.value.label} ---\n${r.value.output}`); } else text(String(r.reason)); }

